<script setup>import InputError from '@/Components/InputError.vue';import{Link,useForm}from'@inertiajs/vue3';const p=defineProps({quotation:{type:Object,default:null},customers:Array,products:Array,plans:Array});const f=useForm({customer_id:p.quotation?.customer_id||'',issue_date:p.quotation?.issue_date?.slice(0,10)||new Date().toISOString().slice(0,10),expiry_date:p.quotation?.expiry_date?.slice(0,10)||'',currency:p.quotation?.currency||'NGN',notes:p.quotation?.notes||'',terms:p.quotation?.terms||'',items:(p.quotation?.items||[]).map(i=>({product_id:i.product_id||'',plan_id:i.plan_id||'',description:i.description,quantity:i.quantity,unit_price:i.unit_price,discount:i.discount,tax:i.tax}))});const add=()=>f.items.push({product_id:'',plan_id:'',description:'',quantity:1,unit_price:0,discount:0,tax:0});if(!f.items.length)add();const submit=()=>p.quotation?f.put(route('admin.quotations.update',p.quotation.uuid)):f.post(route('admin.quotations.store'));</script>
<template><form class="form-card" @submit.prevent="submit"><div class="form-grid"><label>Customer<select v-model="f.customer_id" required><option value="">Select customer</option><option v-for="c in customers" :key="c.id" :value="c.id">{{ c.customer_number }} — {{ c.name }}</option></select><InputError :message="f.errors.customer_id"/></label><label>Currency<input v-model="f.currency" maxlength="3" required class="uppercase"/></label><label>Issue date<input v-model="f.issue_date" type="date" required/></label><label>Expiry date<input v-model="f.expiry_date" type="date" required/><InputError :message="f.errors.expiry_date"/></label></div><section class="space-y-4"><div class="flex justify-between"><h2 class="text-xl font-bold">Line items</h2><button type="button" class="form-secondary-button" @click="add">Add item</button></div><div v-for="(i,x) in f.items" :key="x" class="rounded-xl border p-4"><div class="form-grid"><label>Product<select v-model="i.product_id"><option value="">Custom</option><option v-for="v in products" :key="v.id" :value="v.id">{{ v.name }}</option></select></label><label>Plan<select v-model="i.plan_id"><option value="">None</option><option v-for="v in plans" :key="v.id" :value="v.id">{{ v.name }}</option></select></label><label>Description<input v-model="i.description" required/></label><label>Quantity<input v-model="i.quantity" type="number" min="0.01" step="0.01" required/></label><label>Unit price<input v-model="i.unit_price" type="number" min="0" step="0.01" required/></label><label>Discount amount<input v-model="i.discount" type="number" min="0" step="0.01" required/></label><label>Tax amount<input v-model="i.tax" type="number" min="0" step="0.01" required/></label></div><button type="button" class="text-sm font-bold text-red-600" @click="f.items.splice(x,1)">Remove</button><InputError :message="f.errors[`items.${x}.discount`]"/></div></section><label>Notes<textarea v-model="f.notes" rows="3"/></label><label>Terms<textarea v-model="f.terms" rows="5"/></label><p class="text-sm text-slate-500">All totals are calculated and verified by the server.</p><div class="flex gap-3"><button class="form-button">{{ quotation?'Save quotation':'Create quotation' }}</button><Link :href="route('admin.quotations.index')" class="rounded-xl border px-6 py-3">Cancel</Link></div></form></template>
